//! `duet capture compare`: a melody take's reading plotted and played against its performance.
//!
//! Each test captures a synthetic take with `duet capture melody`, which writes a
//! capture-analysis 1.5 document (a reading with its reader, residual and loss), then compares it; one
//! compares a 1.1 document, a reading with no residual, made from it. The takes are generated by
//! `capture/audio.rs` and written to scratch directories.

#[path = "capture/audio.rs"]
#[expect(
    dead_code,
    reason = "the capture tests' shared generators: these tests use the tones, not the clicks or bursts"
)]
mod audio;

use std::path::{Path, PathBuf};

use duet_e2e::{duet, ok, s, scratch};
use duet_schemas::{Version, kind, schema_url};
use serde_json::Value;

/// C4, E4, G4 and C5, sung 20 cents sharp of A440 from half a second in.
const NOTES: [(u8, f64); 4] = [(60, 0.6), (64, 0.6), (67, 0.6), (72, 0.9)];
const SHARP_CENTS: f64 = 20.0;

/// A take of [`NOTES`] captured at `dir/take`: the recording's path, with `take.capture.duet`
/// and `take.performance.duet.jsonl` beside it.
fn captured(dir: &Path) -> PathBuf {
    let take = dir.join("take.wav");
    audio::write_wav(&take, &audio::notes_off(0.5, &NOTES, SHARP_CENTS));
    let out = duet(dir, &["capture", "melody", s(&take), "--tempo", "120"]);
    ok(&out, "capture melody");
    take
}

fn json(path: &Path) -> Value {
    serde_json::from_str(&std::fs::read_to_string(path).expect("read")).expect("json")
}

/// The reading's notes, and A4 in absolute cents.
fn reading(analysis: &Path) -> (Vec<Value>, f64) {
    let doc = json(analysis);
    let reading = &doc["body"]["reading"];
    let a4 = &reading["tuning"]["a4"];
    let a4 = a4["estimated"]["value"]
        .as_f64()
        .or_else(|| a4["given"].as_f64())
        .expect("a4");
    (reading["notes"].as_array().expect("notes").clone(), a4)
}

/// A two-channel float WAV as its rate and channels.
fn read_wav(path: &Path) -> (u32, Vec<f32>, Vec<f32>) {
    let bytes = std::fs::read(path).expect("read wav");
    assert_eq!(&bytes[..4], b"RIFF");
    assert_eq!(&bytes[8..16], b"WAVEfmt ");
    let u16_at = |i: usize| u16::from_le_bytes([bytes[i], bytes[i + 1]]);
    let u32_at = |i: usize| u32::from_le_bytes(bytes[i..i + 4].try_into().expect("4 bytes"));
    assert_eq!(u16_at(20), 3, "IEEE float");
    assert_eq!(u16_at(22), 2, "two channels");
    let rate = u32_at(24);
    // Chunks after fmt: find data.
    let mut i = 20 + u32_at(16) as usize;
    while &bytes[i..i + 4] != b"data" {
        i += 8 + u32_at(i + 4) as usize;
    }
    let data = &bytes[i + 8..i + 8 + u32_at(i + 4) as usize];
    let samples: Vec<f32> = data
        .as_chunks::<4>()
        .0
        .iter()
        .map(|b| f32::from_le_bytes(*b))
        .collect();
    let left = samples.iter().step_by(2).copied().collect();
    let right = samples.iter().skip(1).step_by(2).copied().collect();
    (rate, left, right)
}

/// The take's samples as duet decodes a 16-bit WAV: each over 32 768.
fn take_samples(path: &Path) -> Vec<f32> {
    let bytes = std::fs::read(path).expect("read take");
    bytes[44..]
        .as_chunks::<2>()
        .0
        .iter()
        .map(|b| f32::from(i16::from_le_bytes(*b)) / 32_768.0)
        .collect()
}

/// The frequency of `samples` at `rate`, from its first rising zero crossing to its last, each
/// placed between samples by straight-line interpolation.
fn frequency(samples: &[f32], rate: u32) -> f64 {
    let crossings: Vec<f64> = samples
        .windows(2)
        .enumerate()
        .filter(|(_, w)| w[0] < 0.0 && w[1] >= 0.0)
        .map(|(i, w)| i as f64 + f64::from(w[0] / (w[0] - w[1])))
        .collect();
    assert!(
        crossings.len() > 10,
        "a tone, not {} crossings",
        crossings.len()
    );
    let span = crossings[crossings.len() - 1] - crossings[0];
    (crossings.len() - 1) as f64 / (span / f64::from(rate))
}

fn hz(cents: f64) -> f64 {
    440.0 * ((cents - 6900.0) / 1200.0).exp2()
}

fn cents_between(a: f64, b: f64) -> f64 {
    1200.0 * (a / b).log2()
}

fn bars(svg: &str, class: &str) -> usize {
    svg.matches(&format!("<rect class=\"{class}")).count()
}

/// Where a note's sine has reached its key: the end of its scoop when the residual measured one,
/// or else where its held pitch begins.
fn settled(note: &Value, rate: u32) -> usize {
    let start = note["start"].as_u64().expect("start");
    let held = note["held_from"].as_u64().expect("held_from");
    note["residual"]["scoop"]["ms"]
        .as_f64()
        .map_or(held, |ms| {
            start + (ms / 1000.0 * f64::from(rate)).round() as u64
        })
        .max(held) as usize
}

/// The witness of the comparison: one bar per note in the plot, the take on the left, and on
/// the right a sine within a cent of each held note's key on the take's tuning; on standard
/// output, each note's residual and the take's loss.
#[test]
fn a_reading_is_plotted_and_played_against_its_take() {
    let dir = scratch("compare");
    let take = captured(&dir);
    let analysis = dir.join("take.capture.duet");
    let current = kind("capture-analysis").expect("a known kind").version;
    assert_eq!(json(&analysis)["duet"]["version"], current.to_string());
    let (notes, a4) = reading(&analysis);
    assert_eq!(notes.len(), NOTES.len(), "{notes:?}");

    let out = duet(&dir, &["capture", "compare", s(&take)]);
    ok(&out, "capture compare");

    let svg = std::fs::read_to_string(dir.join("take.compare.svg")).expect("svg");
    assert!(svg.starts_with("<svg "), "{svg}");
    assert_eq!(bars(&svg, "note"), NOTES.len(), "one bar per note");
    assert_eq!(svg.matches("class=\"performance\"").count(), 1);
    assert!(svg.matches("class=\"residual\"").count() >= NOTES.len());
    assert!(svg.contains("class=\"onset\""));

    let (rate, left, right) = read_wav(&dir.join("take.compare.wav"));
    assert_eq!(rate, audio::RATE);
    let input = take_samples(&take);
    assert_eq!(left.len(), input.len(), "the whole take");
    assert!(
        left.iter().zip(&input).all(|(a, b)| (a - b).abs() < 1e-6),
        "the left channel is the take"
    );
    for (i, note) in notes.iter().enumerate() {
        let key = note["key"].as_f64().expect("key");
        let held = settled(note, rate);
        let end = note["end"].as_u64().expect("end") as usize;
        let margin = (0.03 * f64::from(rate)) as usize;
        let measured = frequency(&right[held + margin..end - margin], rate);
        let want = hz(a4 + 100.0 * (key - 69.0));
        let off = cents_between(measured, want);
        assert!(
            off.abs() < 1.0,
            "note {i}, key {key}: the sine is {off:+.2} cents from it ({measured:.2} Hz)"
        );
        assert_eq!(key as u8, NOTES[i].0, "read on the take's tuning");
    }
    assert!(
        (a4 - 6900.0 - SHARP_CENTS).abs() < 3.0,
        "the take's own tuning, not A440: {a4}"
    );

    let stdout = String::from_utf8(out.stdout).expect("utf-8");
    let lines: Vec<&str> = stdout.lines().filter(|l| !l.starts_with('#')).collect();
    assert_eq!(lines.len(), NOTES.len(), "{stdout}");
    assert!(
        lines[0].contains("C4") && lines[3].contains("C5"),
        "{stdout}"
    );
    assert!(
        stdout.contains("drift/s") && stdout.contains("rest"),
        "{stdout}"
    );
    assert!(stdout.contains("# loss: pitch "), "{stdout}");
    assert!(!stdout.contains("no residual"), "{stdout}");
}

#[test]
fn a_window_cuts_the_plot_the_audio_and_the_notes() {
    let dir = scratch("compare-window");
    let take = captured(&dir);
    let out = duet(
        &dir,
        &[
            "capture",
            "compare",
            s(&take),
            "--from",
            "1.0",
            "--to",
            "2.0",
        ],
    );
    ok(&out, "capture compare --from --to");
    let (rate, left, right) = read_wav(&dir.join("take.compare.1.0-2.0.wav"));
    assert_eq!(left.len(), rate as usize, "one second");
    assert_eq!(right.len(), left.len());
    let input = take_samples(&take);
    assert!(
        left.iter()
            .zip(&input[rate as usize..2 * rate as usize])
            .all(|(a, b)| (a - b).abs() < 1e-6),
        "the left channel is the take's second second"
    );
    // The notes overlapping 1.0..2.0 s: E4 (1.1-1.7) and G4 (1.7-2.3), and C4 until 1.1.
    let (notes, _) = reading(&dir.join("take.capture.duet"));
    let shown = notes
        .iter()
        .filter(|n| {
            let (start, end) = (n["start"].as_u64().unwrap(), n["end"].as_u64().unwrap());
            start < 2 * u64::from(rate) && end > u64::from(rate)
        })
        .count();
    assert!(shown < notes.len(), "the window leaves a note out");
    let svg = std::fs::read_to_string(dir.join("take.compare.1.0-2.0.svg")).expect("svg");
    assert_eq!(bars(&svg, "note"), shown);
    let stdout = String::from_utf8(out.stdout).expect("utf-8");
    assert_eq!(
        stdout.lines().filter(|l| !l.starts_with('#')).count(),
        shown
    );
}

#[test]
fn compare_never_overwrites_and_refuses_what_it_cannot_compare() {
    let dir = scratch("compare-refused");
    let take = captured(&dir);
    ok(
        &duet(&dir, &["capture", "compare", s(&take)]),
        "first compare",
    );
    let svg = std::fs::read(dir.join("take.compare.svg")).expect("svg");
    let wav = std::fs::read(dir.join("take.compare.wav")).expect("wav");
    // Every refusal exits non-zero and names the file it refuses.
    let refused = |args: &[&str], names: &Path, says: &str| {
        let out = duet(&dir, args);
        let err = String::from_utf8_lossy(&out.stderr);
        assert!(
            !out.status.success() && err.contains(says) && err.contains(s(names)),
            "{args:?}: {err}"
        );
    };
    refused(
        &["capture", "compare", s(&take)],
        &dir.join("take.compare.svg"),
        "never overwrites",
    );
    assert_eq!(
        std::fs::read(dir.join("take.compare.svg")).expect("svg"),
        svg
    );
    assert_eq!(
        std::fs::read(dir.join("take.compare.wav")).expect("wav"),
        wav
    );

    std::fs::remove_file(dir.join("take.compare.svg")).expect("remove");
    std::fs::remove_file(dir.join("take.compare.wav")).expect("remove");
    // A shorter recording is not the take the performance was read from.
    let short = dir.join("short.wav");
    audio::write_wav(&short, &audio::silence(1.0));
    refused(
        &["capture", "compare", s(&short), "-o", s(&dir.join("take"))],
        &short,
        "it is not the take",
    );
    let missing = dir.join("missing.wav");
    refused(
        &[
            "capture",
            "compare",
            s(&missing),
            "-o",
            s(&dir.join("take")),
        ],
        &missing,
        "cannot open",
    );
    // An analysis with no reading: a rhythm take's, or one older than 1.1.
    let mut doc = json(&dir.join("take.capture.duet"));
    doc["body"].as_object_mut().unwrap().remove("reading");
    let bare = dir.join("bare.capture.duet");
    std::fs::write(&bare, doc.to_string()).expect("write");
    refused(
        &["capture", "compare", s(&take), "--reading", s(&bare)],
        &bare,
        "holds no reading",
    );
    assert!(!dir.join("bare.compare.svg").exists());
    refused(
        &["capture", "compare", s(&take), "--from", "9"],
        &take,
        "the window holds nothing",
    );
    // A window's outputs are refused as the whole take's are.
    let window = ["capture", "compare", s(&take), "--from", "1", "--to", "2"];
    ok(&duet(&dir, &window), "a window");
    refused(
        &window,
        &dir.join("take.compare.1.0-2.0.svg"),
        "never overwrites",
    );
    let both = duet(
        &dir,
        &["capture", "compare", s(&take), "--legato", "--gapped"],
    );
    assert!(
        !both.status.success(),
        "--legato and --gapped are one or the other"
    );
}

/// `--reading` compares another reading of the same take: the outputs are named after it, its
/// notes are the bars and the sine, and the stem's own reading is drawn beside it.
#[test]
fn another_reading_is_compared_with_the_stems_beside_it() {
    let dir = scratch("compare-other");
    let take = captured(&dir);
    let mut doc = json(&dir.join("take.capture.duet"));
    // The other reading hears the second note a key higher.
    let note = &mut doc["body"]["reading"]["notes"][1];
    note["key"] = Value::from(note["key"].as_u64().unwrap() + 1);
    let other = dir.join("other.capture.duet");
    std::fs::write(&other, doc.to_string()).expect("write");

    let out = duet(
        &dir,
        &["capture", "compare", s(&take), "--reading", s(&other)],
    );
    ok(&out, "capture compare --reading");
    assert!(
        !dir.join("take.compare.svg").exists(),
        "named after the other"
    );
    let svg = std::fs::read_to_string(dir.join("other.compare.svg")).expect("svg");
    assert_eq!(bars(&svg, "note"), NOTES.len());
    assert_eq!(
        bars(&svg, "beside"),
        NOTES.len(),
        "the stem's own, beside it"
    );

    let (notes, a4) = reading(&other);
    let (rate, _, right) = read_wav(&dir.join("other.compare.wav"));
    let n = &notes[1];
    let (held, end) = (settled(n, rate), n["end"].as_u64().unwrap() as usize);
    let margin = (0.03 * f64::from(rate)) as usize;
    let measured = frequency(&right[held + margin..end - margin], rate);
    let want = hz(a4 + 100.0 * (f64::from(NOTES[1].0 + 1) - 69.0));
    assert!(cents_between(measured, want).abs() < 1.0, "{measured} Hz");
    let stdout = String::from_utf8(out.stdout).expect("utf-8");
    assert!(stdout.contains("F4"), "{stdout}");
}

/// A reading written before the residual, capture-analysis 1.1, still compares: its notes are
/// the bars and the sine, and standard output says it holds no residual or loss.
#[test]
fn a_reading_with_no_residual_compares() {
    let dir = scratch("compare-1-1");
    let take = captured(&dir);
    let mut doc = json(&dir.join("take.capture.duet"));
    let body = doc["body"]["reading"].as_object_mut().expect("a reading");
    // Every field newer than 1.1: the residual (1.2) and the reader (1.3).
    body.remove("residual");
    body.remove("reader");
    for note in body["notes"].as_array_mut().expect("notes") {
        note.as_object_mut().expect("a note").remove("residual");
    }
    let old = Version::new(1, 1);
    doc["duet"]["version"] = Value::from(old.to_string());
    doc["$schema"] = Value::from(schema_url("capture-analysis", old));
    let old = dir.join("old.capture.duet");
    std::fs::write(&old, doc.to_string()).expect("write");

    let out = duet(
        &dir,
        &["capture", "compare", s(&take), "--reading", s(&old)],
    );
    ok(&out, "capture compare a 1.1 reading");
    let svg = std::fs::read_to_string(dir.join("old.compare.svg")).expect("svg");
    assert_eq!(bars(&svg, "note"), NOTES.len());
    let (notes, a4) = reading(&old);
    let (rate, _, right) = read_wav(&dir.join("old.compare.wav"));
    for note in &notes {
        let (held, end) = (settled(note, rate), note["end"].as_u64().unwrap() as usize);
        let margin = (0.03 * f64::from(rate)) as usize;
        let measured = frequency(&right[held + margin..end - margin], rate);
        let want = hz(a4 + 100.0 * (note["key"].as_f64().unwrap() - 69.0));
        assert!(cents_between(measured, want).abs() < 1.0, "{measured} Hz");
    }
    let stdout = String::from_utf8(out.stdout).expect("utf-8");
    assert!(stdout.contains("no residual or loss"), "{stdout}");
    assert!(!stdout.contains("# loss:"), "{stdout}");
}

/// The longest gap the sine bridges: `BRIDGE_SECS` in `wav.rs`.
const BRIDGE_SECS: f64 = 0.2;

/// C4, then E4 after a short gap (a consonant's), then G4 after a rest (a breath's), sung 20 cents
/// sharp from half a second in, captured at `dir/take`.
fn captured_with_gaps(dir: &Path) -> PathBuf {
    let tone = |key: u8, secs: f64| {
        let mut t = audio::notes_off(0.0, &[(key, secs)], SHARP_CENTS);
        t.truncate((secs * f64::from(audio::RATE)).round() as usize);
        t
    };
    let mut samples = audio::silence(0.5);
    samples.extend(tone(60, 0.6));
    samples.extend(audio::silence(0.12));
    samples.extend(tone(64, 0.6));
    samples.extend(audio::silence(0.5));
    samples.extend(tone(67, 0.6));
    samples.extend(audio::silence(1.0));
    let take = dir.join("take.wav");
    audio::write_wav(&take, &samples);
    ok(
        &duet(dir, &["capture", "melody", s(&take), "--tempo", "120"]),
        "capture melody",
    );
    take
}

/// The right channel of a compare run with `flags`, moved aside so the next run can write.
fn right_channel(dir: &Path, take: &Path, flags: &[&str]) -> Vec<f32> {
    let mut args = vec!["capture", "compare", s(take)];
    args.extend(flags);
    ok(&duet(dir, &args), &format!("capture compare {flags:?}"));
    let (_, _, right) = read_wav(&dir.join("take.compare.wav"));
    std::fs::remove_file(dir.join("take.compare.wav")).expect("remove");
    std::fs::remove_file(dir.join("take.compare.svg")).expect("remove");
    right
}

/// The interior of the gap after note `i`: from 20 ms after it ends to 20 ms before the next
/// starts, past each phrase's 10 ms fade.
fn gap_after(notes: &[Value], i: usize, rate: u32) -> std::ops::Range<usize> {
    let margin = (0.02 * f64::from(rate)) as usize;
    let end = notes[i]["end"].as_u64().expect("end") as usize;
    let next = notes[i + 1]["start"].as_u64().expect("start") as usize;
    assert!(
        next > end + 2 * margin,
        "a gap after note {i}: {end}..{next}"
    );
    end + margin..next - margin
}

fn silent(samples: &[f32]) -> bool {
    samples.iter().all(|x| *x == 0.0)
}

/// The sine holds through a gap shorter than the threshold, at the key of the note before, and is
/// silent through one at or above it; `--legato` holds through both and `--gapped` silences both.
#[test]
fn the_sine_bridges_a_short_gap_and_falls_silent_at_a_rest() {
    let dir = scratch("compare-gaps");
    let take = captured_with_gaps(&dir);
    let (notes, a4) = reading(&dir.join("take.capture.duet"));
    assert_eq!(notes.len(), 3, "{notes:?}");
    let rate = audio::RATE;
    let gap = |i: usize| {
        (notes[i + 1]["start"].as_u64().unwrap() - notes[i]["end"].as_u64().unwrap()) as f64
            / f64::from(rate)
    };
    assert!(
        gap(0) < BRIDGE_SECS,
        "the short gap is read short: {} s",
        gap(0)
    );
    assert!(gap(1) >= BRIDGE_SECS, "the rest is read long: {} s", gap(1));
    let (short, rest) = (gap_after(&notes, 0, rate), gap_after(&notes, 1, rate));
    let held = |right: &[f32], range: std::ops::Range<usize>, i: usize| {
        let measured = frequency(&right[range], rate);
        let want = hz(a4 + 100.0 * (notes[i]["key"].as_f64().unwrap() - 69.0));
        let off = cents_between(measured, want);
        assert!(
            off.abs() < 1.0,
            "held at note {i}'s key: {off:+.2} cents off"
        );
    };

    let bridged = right_channel(&dir, &take, &[]);
    held(&bridged, short.clone(), 0);
    assert!(silent(&bridged[rest.clone()]), "silent at the rest");

    let legato = right_channel(&dir, &take, &["--legato"]);
    held(&legato, short.clone(), 0);
    held(&legato, rest.clone(), 1);

    let gapped = right_channel(&dir, &take, &["--gapped"]);
    assert!(silent(&gapped[short]), "--gapped: silent in the short gap");
    assert!(silent(&gapped[rest]), "--gapped: silent at the rest");
}

/// A note the reading drops leaves a gap as long as the note, and is heard as silence, not as the
/// note before held on; `--legato` holds the note before through it.
#[test]
fn a_dropped_note_is_heard_as_silence() {
    let dir = scratch("compare-dropped");
    let take = captured(&dir);
    let mut doc = json(&dir.join("take.capture.duet"));
    doc["body"]["reading"]["notes"]
        .as_array_mut()
        .expect("notes")
        .remove(1);
    let dropped = dir.join("dropped.capture.duet");
    std::fs::write(&dropped, doc.to_string()).expect("write");
    let (notes, a4) = reading(&dropped);
    let rate = audio::RATE;
    let range = gap_after(&notes, 0, rate);
    assert!(range.len() as f64 / f64::from(rate) >= BRIDGE_SECS);

    let run = |flags: &[&str]| {
        let mut args = vec!["capture", "compare", s(&take), "--reading", s(&dropped)];
        args.extend(flags);
        ok(&duet(&dir, &args), &format!("capture compare {flags:?}"));
        let (_, _, right) = read_wav(&dir.join("dropped.compare.wav"));
        std::fs::remove_file(dir.join("dropped.compare.wav")).expect("remove");
        std::fs::remove_file(dir.join("dropped.compare.svg")).expect("remove");
        right
    };
    assert!(
        silent(&run(&[])[range.clone()]),
        "the dropped note is silence"
    );
    let legato = run(&["--legato"]);
    let measured = frequency(&legato[range], rate);
    let want = hz(a4 + 100.0 * (notes[0]["key"].as_f64().unwrap() - 69.0));
    assert!(cents_between(measured, want).abs() < 1.0, "{measured} Hz");
}

/// A windowed run beside a run of the whole take writes both: the window's outputs are named after
/// it, and the whole take's are left as they were.
#[test]
fn a_window_is_named_after_it_beside_the_whole_take() {
    let dir = scratch("compare-window-names");
    let take = captured(&dir);
    ok(
        &duet(&dir, &["capture", "compare", s(&take)]),
        "the whole take",
    );
    let whole = std::fs::read(dir.join("take.compare.wav")).expect("wav");
    let svg = std::fs::read(dir.join("take.compare.svg")).expect("svg");
    ok(
        &duet(
            &dir,
            &["capture", "compare", s(&take), "--from", "1", "--to", "2.5"],
        ),
        "a window after the whole take",
    );
    ok(
        &duet(&dir, &["capture", "compare", s(&take), "--from", "1"]),
        "a window to the end",
    );
    ok(
        &duet(&dir, &["capture", "compare", s(&take), "--to", "1"]),
        "a window from the start",
    );
    assert_eq!(
        std::fs::read(dir.join("take.compare.wav")).expect("wav"),
        whole
    );
    assert_eq!(
        std::fs::read(dir.join("take.compare.svg")).expect("svg"),
        svg
    );
    let rate = audio::RATE as usize;
    let (_, left, _) = read_wav(&dir.join("take.compare.1.0-2.5.wav"));
    assert_eq!(left.len(), rate * 3 / 2, "1.0 to 2.5 s");
    assert!(dir.join("take.compare.1.0-2.5.svg").exists());
    let (_, left, _) = read_wav(&dir.join("take.compare.0.0-1.0.wav"));
    assert_eq!(left.len(), rate, "0 to 1 s");
    let (_, left, _) = read_wav(&dir.join("take.compare.1.0-end.wav"));
    let (_, all, _) = read_wav(&dir.join("take.compare.wav"));
    assert_eq!(left.len(), all.len() - rate, "1 s to the end");
}
